// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumberSeed, uint256 randomTimestamp) public {
        vm.assume(blockNumberSeed > 0);
        vm.roll(blockNumberSeed);
        vm.warp(randomTimestamp);
        uint256 initialBalance = address(c).balance;
        bool expectsTransfer = (block.number % 15 == 0);
        uint256 amount = 10 ether;
        bool success = true;
        vm.deal(address(this), amount);
        (bool ok,) = address(c).call{value: amount}("");
        if (!ok) {
            success = false;
        }
        uint256 finalBalance = address(c).balance;
        if (success) {
            if (expectsTransfer) {
                assertTrue(finalBalance == initialBalance);
            } else {
                assertTrue(finalBalance == initialBalance + amount);
            }
        }
    }
}

